// Nœud n8n "Filtrer & préparer" (Code, runOnceForAllItems)
// Décode le corps des emails, applique les règles déterministes LinkedIn,
// extrait URL/Poste/Lieu/Mode pour les confirmations Envoyé, et construit
// le prompt Claude. Sortie : un item par email à classifier.
//
// Les alertes d'offres LinkedIn (jobalerts-noreply) ne sont plus ignorées :
// leur digest text/plain est découpé en cartes (une par offre) taguées
// kind:'veille'. Un Switch en aval ("Veille ?") sépare kind:'veille' du flux
// Candidatures (kind:'candidature'). Cf. veille-jobalerts.feature.md.

const items = $input.all();
const results = [];

const decodeB64 = (data) => {
  if (!data) return '';
  try { return Buffer.from(data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8'); }
  catch (e) { return ''; }
};

const extractText = (parts) => {
  if (!Array.isArray(parts)) return '';
  let text = '';
  for (const part of parts) {
    if (part.mimeType === 'text/plain' && part.body?.data) text += decodeB64(part.body.data) + ' ';
    else if (Array.isArray(part.parts)) text += extractText(part.parts);
  }
  return text;
};

// Lit un en-tête depuis le dict normalisé du nœud Gmail v2 (clés minuscules,
// valeurs de la forme "Nom: valeur").
const headerFromMap = (email, name) => {
  const h = email.headers;
  if (h && typeof h === 'object' && !Array.isArray(h)) {
    const raw = h[name.toLowerCase()];
    if (raw) return String(raw).replace(new RegExp('^\\s*' + name + '\\s*:\\s*', 'i'), '').trim();
  }
  return '';
};

// Récupère un en-tête quel que soit le format de sortie du nœud Gmail :
//  - brut (get full)            : email.payload.headers = [{name, value}]
//  - normalisé (node v2, simple:false) : champ direct minuscule (email.subject / email.date / …)
//    + dict email.headers {<nom-minuscule>: "Nom: valeur"}
// ⚠️ Le nœud "Gmail — Emails de la veille" renvoie la forme NORMALISÉE (pas de payload) :
// sans ce support, subject/from/date/domain remontaient tous vides (dates jamais écrites,
// règles LinkedIn forcées et filtrage jobalerts inopérants).
const getHeader = (email, name) => {
  const headers = email.payload?.headers;
  if (Array.isArray(headers)) {
    const found = headers.find(h => (h.name || '').toLowerCase() === name.toLowerCase());
    if (found) return found.value || '';
  }
  const low = name.toLowerCase();
  if (typeof email[low] === 'string' && email[low]) return email[low];
  const fromMap = headerFromMap(email, name);
  if (fromMap) return fromMap;
  const cap = name.charAt(0).toUpperCase() + name.slice(1);
  return email[name] || email[cap] || '';
};

const cutName = (s) => s.split(/\s[-|–—:]\s|\n|\bpour\b|\bfor\b/i)[0].trim().slice(0, 60);
const escRe = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Normalise vers les valeurs FR utilisées dans Airtable Candidatures : "À distance" / "Hybride" / "Sur site"
const cleanMode = (raw) => {
  const m = String(raw || '').toLowerCase();
  if (/(à\s*distance|\ba\s*distance\b|remote|télétravail|teletravail|full\s*remote)/.test(m)) return 'À distance';
  if (/(hybride|hybrid)/.test(m)) return 'Hybride';
  if (/(sur\s*(?:site|place)|on[-\s]?site|présentiel|presentiel)/.test(m)) return 'Sur site';
  return '';
};

// Trouve une URL d'offre LinkedIn dans un texte (HTML ou plain)
const findLinkedInJobUrl = (text) => {
  if (!text) return '';
  const m = String(text).match(/https?:\/\/(?:[\w.-]+\.)?linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)/i);
  return m ? `https://www.linkedin.com/jobs/view/${m[1]}/` : '';
};

// Cherche l'URL d'offre dans toutes les parties du payload (plain + html)
const findLinkedInJobUrlInPayload = (payload) => {
  if (!payload) return '';
  if (payload.body?.data) {
    const u = findLinkedInJobUrl(decodeB64(payload.body.data));
    if (u) return u;
  }
  if (Array.isArray(payload.parts)) {
    for (const p of payload.parts) {
      const u = findLinkedInJobUrlInPayload(p);
      if (u) return u;
    }
  }
  return '';
};

// --- Parseur de digest d'alertes emploi LinkedIn (jobalerts-noreply) ---
// Le corps text/plain liste les offres en blocs séparés par des lignes de tirets :
//   <Poste> / <Employeur> / <Lieu> / [badge…] / "Voir l'offre d'emploi : <URL …/jobs/view/JOBID/…>"
// Validé sur emails réels (2026-06-16). Pas de description du poste dans l'email
// (contrainte fiche) → on n'extrait que titre/employeur/lieu/mode + jobId/URL.
// Renvoie une carte par jobId (dédup intra-email ; dédup inter-jours = upsert Airtable).
const VEILLE_BADGES = /^(Top candidat|Croissance rapide|Recrutement actif|Cette entreprise recrute activement|Soyez parmi les premiers|Postulez avec|Candidature simplifiée|Easy Apply|Reprend contact|Forte affinité|Promu|En vedette|Actively recruiting|Be an early applicant|Top applicant|Salaire\b|\d+\s+relation)/i;

const parseJobAlertDigest = (plain) => {
  const cards = [];
  if (!plain) return cards;
  const seen = new Set();
  // Nom de l'alerte (recherche LinkedIn enregistrée) — contexte utile au triage
  const alertM = plain.match(/Votre alerte Emploi pour\s+(.+)/i);
  const alertName = alertM ? alertM[1].trim().slice(0, 200) : '';
  const blocks = plain.split(/\n[ \t]*-{3,}[ \t]*\n/);
  for (const block of blocks) {
    const jm = block.match(/linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)/i);
    if (!jm) continue;                       // en-tête / pied de page sans offre
    const jobId = jm[1];
    if (seen.has(jobId)) continue;           // dédup intra-email
    seen.add(jobId);
    const url = `https://www.linkedin.com/jobs/view/${jobId}/`;
    const lines = block.split('\n')
      .map(l => l.replace(/\s+/g, ' ').trim())
      .filter(Boolean)
      .filter(l => !/^Votre alerte Emploi pour/i.test(l))
      .filter(l => !/^Voir l.offre d.emploi\s*:/i.test(l))
      .filter(l => !VEILLE_BADGES.test(l));
    const poste = (lines[0] || '').slice(0, 200);
    const employeur = (lines[1] || '').slice(0, 120);
    let lieu = (lines[2] || '').slice(0, 120);
    // Mode parfois accolé au lieu : "France (à distance)", "Paris (Hybride)"
    let mode = '';
    const lp = lieu.match(/^(.*?)\s*\(([^)]+)\)\s*$/);
    if (lp) { const m = cleanMode(lp[2]); if (m) { mode = m; lieu = lp[1].trim(); } }
    if (!mode) mode = cleanMode(lieu);
    cards.push({ jobId, url, employeur, poste, lieu, mode, alertName });
  }
  return cards;
};

for (const item of items) {
  const email = item.json;

  const subject = getHeader(email, 'Subject');
  // From : objet normalisé {value:[{address,name}]} (node v2) OU en-tête brut.
  const fromObj = email.from;
  let fromRaw = '';
  if (fromObj && typeof fromObj === 'object' && Array.isArray(fromObj.value) && fromObj.value[0]) {
    const v = fromObj.value[0];
    fromRaw = v.name ? `${v.name} <${v.address || ''}>` : (v.address || '');
  } else {
    fromRaw = getHeader(email, 'From');
  }
  const dateRaw = getHeader(email, 'Date'); // node v2 : déjà ISO (ex. 2026-06-15T22:09:30.000Z)
  const fromEmail = (
    (fromObj && typeof fromObj === 'object' && fromObj.value && fromObj.value[0] && fromObj.value[0].address)
    || (fromRaw.match(/<([^>]+)>/) || [])[1]
    || fromRaw.trim()
    || ''
  ).toLowerCase();
  const domain = fromEmail.includes('@') ? fromEmail.split('@')[1] : '';
  const snippet = email.snippet
    || (typeof email.text === 'string' ? email.text.replace(/\s+/g, ' ').trim().slice(0, 400) : '');
  const isLinkedIn = domain.includes('linkedin.com');

  // Règles déterministes LinkedIn (sur sujet + aperçu)
  let forcedReponse = null;
  let forcedSociete = null;
  if (isLinkedIn) {
    const head = `${subject}\n${snippet}`;
    let m;
    if ((m = head.match(/your application was sent to\s+(.+)/i)) ||
        (m = head.match(/votre candidature a été envoyée à\s+(.+)/i)) ||
        (m = head.match(/candidature(?:\s+a(?:\s+bien)?\s+été)?\s+envoyée\s+à\s+(.+)/i))) {
      forcedReponse = 'Envoyé'; forcedSociete = cutName(m[1]);
    } else if ((m = head.match(/your application was viewed by\s+(.+)/i)) ||
               (m = head.match(/candidature a été consultée par\s+(.+)/i))) {
      forcedReponse = 'A/R'; forcedSociete = cutName(m[1]);
    } else if ((m = head.match(/derni[eè]re nouvelle de\s+(.+)/i))) {
      forcedReponse = 'Non'; forcedSociete = cutName(m[1]);
    }
  }

  // Alertes d'offres LinkedIn -> branche Veille (parse du digest en cartes)
  if (!forcedReponse && fromEmail === 'jobalerts-noreply@linkedin.com') {
    let plain = '';
    if (email.payload && Array.isArray(email.payload.parts)) plain = extractText(email.payload.parts);
    else if (email.payload?.body?.data) plain = decodeB64(email.payload.body.data);
    if (!plain) plain = email.plaintextBody || email.text || '';
    for (const c of parseJobAlertDigest(plain)) {
      results.push({
        json: {
          kind: 'veille',
          jobId: c.jobId, url: c.url,
          employeur: c.employeur, poste: c.poste, lieu: c.lieu, mode: c.mode,
          alertName: c.alertName,
          emailId: email.id || '', date: dateRaw,
        },
      });
    }
    continue; // ne pas envoyer ces emails dans le flux Candidatures
  }

  let bodyRaw = '';
  if (email.payload) {
    if (Array.isArray(email.payload.parts)) bodyRaw = extractText(email.payload.parts);
    else if (email.payload.body?.data) bodyRaw = decodeB64(email.payload.body.data);
  }
  if (!bodyRaw) bodyRaw = email.text || email.html || snippet || '';

  let bodyClean = String(bodyRaw).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (bodyClean.length > 2500) bodyClean = bodyClean.slice(0, 1800) + ' […] ' + bodyClean.slice(-700);

  // Enrichissement LinkedIn (Envoyé uniquement) — URL / Poste / Lieu / Mode
  let forcedUrl = '';
  let forcedPoste = null;
  let forcedLieu = null;
  let forcedMode = null;
  if (isLinkedIn && forcedReponse === 'Envoyé' && forcedSociete) {
    forcedUrl = findLinkedInJobUrlInPayload(email.payload);

    // Pattern : "<Société> <Poste> <Société> · <Lieu> (<Mode>?) ... Candidature/Application/Voir/View"
    const escSoc = escRe(forcedSociete);
    const stop = '(?:\\s+Candidature\\s+envoyée|\\s+Application\\s+sent|\\s+View\\s+job|\\s+Voir\\s+l|\\s+Postuler|$)';
    const re = new RegExp(
      `${escSoc}\\s+([^·•]+?)\\s+${escSoc}\\s*[·•]\\s*([^·•]+?)${stop}`,
      'i'
    );
    const mm = bodyClean.match(re);
    if (mm) {
      forcedPoste = mm[1].trim().slice(0, 200);
      const meta = mm[2].trim();
      const lm = meta.match(/^(.+?)\s*(?:\(([^)]+)\))?\s*$/);
      if (lm) {
        forcedLieu = lm[1].trim().slice(0, 100);
        forcedMode = cleanMode(lm[2] || meta);
      }
    }
  }

  const customId = ('m_' + (email.id || String(results.length)))
    .replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 64);

  const claudePrompt = `Analyse cet email de candidature à l'emploi (en français) et classe la réponse de l'employeur.

Expéditeur : ${fromRaw}
Domaine expéditeur : ${domain}
Sujet : ${subject}
Corps : ${bodyClean || snippet}

Réponds UNIQUEMENT avec ce JSON, sans texte ni balises autour :
{"recrutement": true/false, "societe": "... ou null", "poste": "... ou null", "reponse": "A/R|Oui|Non", "confidence": "high|medium|low", "note": "1 phrase"}

DÉFINITIONS
- recrutement=true : email lié à une candidature précise (accusé de réception d'ATS, refus, invitation entretien, message d'un recruteur sur une candidature).
- recrutement=false : alertes/offres non sollicitées, newsletters ; emails d'AUTHENTIFICATION / code de connexion / vérification ; emails de BIENVENUE / création de compte / inscription à une plateforme ; invitations à une CONFÉRENCE / webinaire / événement (≠ entretien d'embauche) ; notifs bancaires, factures, pub, réseaux sociaux.
- societe : l'ENTREPRISE qui recrute. Si elle n'est pas explicite, DÉDUIS-LA de la signature, de l'adresse postale, du logo/nom cité dans le corps, ou du domaine de l'expéditeur. Jamais la plateforme/ATS ni le cabinet (ignorer Welcome to the Jungle, Greenhouse, Lever, Workday, LinkedIn). null seulement si vraiment introuvable.
- poste : déduis l'intitulé depuis le sujet, le corps ou la signature. null si introuvable.

CLASSEMENT DE reponse — lis le CORPS, pas seulement l'objet :
- "A/R" = accusé de réception, AUCUNE décision : « bien reçu votre candidature », « candidature enregistrée », « merci pour votre candidature », confirmation automatique.
- "Non" = refus : « ne donnerons pas suite », « profil n'a pas été retenu », « malheureusement », « regret », « unfortunately ».
- "Oui" = suite positive RÉELLE : invitation entretien/échange/appel/visio, test ou screening de sélection, « souhaitons vous rencontrer », « vos disponibilités », « prochaine étape ». PAS une invitation à une conférence/événement ni une simple inscription.

RÈGLES
- Un accusé de réception n'est PAS un refus. A/R ≠ Non ≠ Oui.
- En cas de doute entre les trois (si c'est bien du recrutement) → "A/R".`;

  results.push({
    json: {
      kind: 'candidature',
      customId, emailId: email.id || '', subject, fromRaw, fromEmail,
      date: dateRaw, domain, snippet, bodyClean, claudePrompt,
      forcedReponse, forcedSociete, forcedUrl, forcedPoste, forcedLieu, forcedMode,
    },
  });
}

return results;

const items = $input.all();

const requests = items.map((item) => ({
  custom_id: item.json.customId,
  params: {
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 512,
    system: 'Tu extrais des infos depuis des emails de recrutement. Réponds UNIQUEMENT en JSON valide.',
    messages: [{ role: 'user', content: item.json.claudePrompt }],
  },
}));

// Garde-fou: un batch vide renverrait un 400 côté Anthropic.
if (requests.length === 0) {
  throw new Error('Aucun email à classifier (0 requête) — rien à envoyer au batch.');
}

return [{ json: { requests, count: requests.length } }];

// Nœud n8n "Matcher & décider" (Code, runOnceForAllItems)
// Lit les résultats du batch (JSONL) + la liste Airtable, rapproche chaque
// email d'une candidature existante, et décide : create / update / skip / review.
// Propage en sortie les enrichissements LinkedIn (URL, Lieu, Mode).

const DENY = new Set(['indigoneo']);

// Hiérarchie des statuts : on n'avance que vers l'avant
const RANK = { '': 0, 'neant': 0, 'envoye': 1, 'a/r': 2, 'ar': 2, 'oui': 3, 'non': 3 };
const rankOf = (rp) => RANK[String(rp || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')] ?? 0;

const toIso = (s) => { if (!s) return ''; const d = new Date(s); return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10); };

const normalize = (s) => String(s || '')
  .toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/\b(sas|sasu|sa|sarl|inc|ltd|llc|gmbh|group|groupe|technologies|tech|recruitment|recrutement|staffing)\b/g, '')
  .replace(/[^a-z0-9]/g, '');

const getField = (f, name) => {
  if (!f) return '';
  if (f[name] != null) return f[name];
  const norm = (s) => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const target = norm(name);
  for (const k of Object.keys(f)) if (norm(k) === target) return f[k];
  return '';
};

const indexed = $input.all().map((i) => {
  const f = i.json.fields || i.json;
  return {
    id: getField(f, 'id') || i.json.id,
    societe: getField(f, 'societe'),
    poste: getField(f, 'poste'),
    reponse: getField(f, 'reponse'),
    key: normalize(getField(f, 'societe')),
  };
});

const findMatch = (societe, meta) => {
  const keyS = normalize(societe);
  if (keyS.length > 1) {
    const m = indexed.find(r => r.key && (r.key === keyS || r.key.includes(keyS) || keyS.includes(r.key)));
    if (m) return m;
  }
  const hay = normalize(`${meta.subject || ''} ${meta.snippet || ''} ${meta.bodyClean || ''} ${meta.fromRaw || ''}`);
  if (hay) {
    const hits = indexed
      .filter(r => r.key && r.key.length >= 4 && hay.includes(r.key))
      .sort((a, b) => b.key.length - a.key.length);
    if (hits.length) return hits[0];
  }
  const keyD = normalize((meta.domain || '').split('.')[0]);
  if (keyD.length > 2) {
    const m = indexed.find(r => r.key && (r.key.includes(keyD) || keyD.includes(r.key)));
    if (m) return m;
  }
  return null;
};

const metaById = {};
for (const it of $('Filtrer & préparer').all()) {
  metaById[it.json.customId] = it.json;
}

const r = $('Récupérer résultats').first().json;
const raw = (typeof r === 'string') ? r : (r.data || r.body || r.text || '');
const lines = String(raw).split('\n').map(l => l.trim()).filter(Boolean);

const out = [];
for (const line of lines) {
  let entry;
  try { entry = JSON.parse(line); } catch (e) { continue; }

  const meta = metaById[entry.custom_id];
  if (!meta) continue;

  let extracted = { recrutement: false, societe: null, poste: null, reponse: 'A/R', confidence: 'low', note: '' };
  if (entry.result && entry.result.type === 'succeeded') {
    try {
      const text = entry.result.message?.content?.[0]?.text || '';
      const clean = text.replace(/```json\n?/g, '').replace(/```/g, '').trim();
      extracted = { ...extracted, ...JSON.parse(clean) };
    } catch (e) { /* défaut conservé */ }
  }

  const forced = !!meta.forcedReponse;
  if (extracted.recrutement !== true && !forced) continue;

  // société + fiabilité (forcée OU extraite par Claude = fiable ; fallback domaine = non fiable)
  let societe, societeReliable;
  if (meta.forcedSociete) { societe = meta.forcedSociete; societeReliable = true; }
  else if (extracted.societe && extracted.societe !== 'null') { societe = extracted.societe; societeReliable = true; }
  else { societe = meta.domain ? meta.domain.split('.')[0] : ''; societeReliable = false; }

  // Poste : préfère l'extraction LinkedIn déterministe, sinon Claude
  const poste = meta.forcedPoste
    ? meta.forcedPoste
    : ((extracted.poste && extracted.poste !== 'null') ? extracted.poste : '');

  // Enrichissements LinkedIn (vides pour les autres emails)
  const lieu = meta.forcedLieu || '';
  const mode = meta.forcedMode || '';
  const linkedinUrl = meta.forcedUrl || '';

  const reponse = forced
    ? meta.forcedReponse
    : (['Oui', 'Non', 'A/R'].includes(extracted.reponse) ? extracted.reponse : 'A/R');

  if (DENY.has(normalize(societe))) continue;

  const match = findMatch(societe, meta);

  let action, airtableId = null;
  if (match) {
    airtableId = match.id;
    action = rankOf(reponse) > rankOf(match.reponse) ? 'update' : 'skip';
  } else if (societeReliable && normalize(societe).length >= 2) {
    action = 'create';
  } else {
    action = 'review';
  }

  out.push({
    json: {
      action, airtableId, societe, poste, reponse,
      lieu, mode, linkedinUrl,
      subject: meta.subject, fromRaw: meta.fromRaw, date: toIso(meta.date),
      note: extracted.note || '',
      gmailLink: meta.emailId ? `https://mail.google.com/mail/u/0/#all/${meta.emailId}` : '',
      domain: meta.domain, emailId: meta.emailId,
      confidence: extracted.confidence || 'low',
      forced, existingReponse: match ? match.reponse : null,
    },
  });
}

// Dédoublonnage intra-run : create/update oui ; review JAMAIS (l'upsert Airtable gère le cross-run)
const best = new Map();
const reviews = [];
for (const o of out) {
  if (o.json.action === 'review') { reviews.push(o); continue; }
  const k = (o.json.action === 'create') ? ('soc:' + normalize(o.json.societe)) : ('id:' + o.json.airtableId);
  const prev = best.get(k);
  if (!prev || rankOf(o.json.reponse) > rankOf(prev.json.reponse)) best.set(k, o);
}
return [...best.values(), ...reviews];

// Nœud n8n "Prépa triage Veille" (Code, runOnceForAllItems)
// Construit UNE seule requête de triage pour TOUTES les offres du jour (évite le
// rate-limit Anthropic d'un appel par carte, et laisse l'IA comparer les offres
// entre elles). Sort un unique item { prompt, cards } consommé par l'appel Claude.

const cards = $input.all().map((it) => it.json);

const PROFIL = `Profil candidat : consultant senior independant, 25 ans d'experience, 100% assurance & finance. Cherche mission freelance/contract/interim (CDI senior finance possible), full remote ou hybride privilegie, TJM >= 1000 EUR/j. Ouvert a l'international en remote (EMEA, Amerique du Nord, APAC).`;

const RUBRIQUE = `Classe CHAQUE offre par pertinence pour ce profil, en te basant sur titre + employeur + lieu UNIQUEMENT (pas de description disponible).
- "Haute" = coeur de cible a seniorite senior : transformation finance/assurance, PMO / Program / Project Manager en finance/assurance/banque/asset management, AMOA / Business Analyst finance, Interim Finance Manager / Head of, comptabilite des investissements (IFRS 9, IFRS 17, Solvency II, fund accounting, sous-ledger titres), reporting reglementaire (ACPR, ORSA, QRT, RSR/SFCR), implementation SimCorp / Clearwater / Bloomberg / OMS, migration & apurement comptable. Un lieu en Europe/EMEA, a l'etranger ou non precise NE PENALISE PAS (remote international accepte).
- "Moyenne" = finance/PMO senior hors assurance stricte (corporate finance, banque generaliste, FP&A senior), ou coeur de cible avec un doute reel sur la seniorite.
- "Hors-cible" = junior/stage/alternance, OU metier hors finance/assurance : IT/dev pur, e-commerce, energie, marketing, RH, commercial, conseil generaliste sans ancrage finance/assurance.
REGLES : ne pas inventer d'info ; l'ABSENCE de mention "remote/teletravail" n'est PAS un signal negatif (les alertes ne le precisent jamais) ; un "Project Manager" sans secteur finance/assurance identifiable = Hors-cible ; en cas d'hesitation entre Haute et Moyenne sur une offre clairement finance/assurance senior, choisir Haute.`;

const lignes = cards
  .map((c, i) => `${i + 1}. Poste: ${c.poste || ''} | Employeur: ${c.employeur || ''} | Lieu: ${c.lieu || ''}`)
  .join('\n');

const prompt = `${PROFIL}\n\n${RUBRIQUE}\n\nReponds UNIQUEMENT avec un tableau JSON, un objet par offre, DANS L'ORDRE, sans texte autour :\n[{"i":1,"pertinence":"Haute|Moyenne|Hors-cible","raison":"<=12 mots en francais"}]\n\nOFFRES :\n${lignes}`;

return [{ json: { prompt, cards, count: cards.length } }];

// Nœud n8n "Parser triage Veille" (Code, runOnceForAllItems)
// Lit la réponse unique du triage (tableau JSON, un objet par offre dans l'ordre)
// et la rattache à chaque carte par index. Sort une carte par offre (jobId + pertinence).
const src = $('Prépa triage Veille').first().json;
const cards = src.cards || [];

let arr = [];
try {
  const txt = ($json && $json.content && $json.content[0] && $json.content[0].text) || '';
  const m = txt.match(/\[[\s\S]*\]/);
  if (m) arr = JSON.parse(m[0]);
} catch (e) { /* tableau vide => pertinence vide, à trier à la main */ }

const byI = {};
for (const o of arr) { if (o && o.i != null) byI[Number(o.i)] = o; }

const valid = ['Haute', 'Moyenne', 'Hors-cible'];
const toIso = (s) => { if (!s) return ''; const d = new Date(s); return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10); };

return cards.map((c, idx) => {
  const o = byI[idx + 1] || {};
  let pertinence = o.pertinence;
  if (!valid.includes(pertinence)) pertinence = '';
  return {
    json: {
      jobId: c.jobId, employeur: c.employeur, poste: c.poste, lieu: c.lieu,
      mode: c.mode, url: c.url, alertName: c.alertName, date: toIso(c.date),
      pertinence, raison: o.raison || '',
    },
  };
});

// Nœud n8n "Veille décider" (Code, runOnceForAllItems)
// Décide create vs update pour chaque carte, SANS dépendre du pairedItem :
// le nœud "Chercher Veille" (search Airtable) casse l'appariement 1-pour-1, donc
// on rapproche en JS via .all() (même principe que "Matcher & décider").
// Index des lignes Veille existantes (résultats du search) : jobId -> id Airtable.
const existing = {};
for (const it of $('Chercher Veille').all()) {
  const j = it.json || {};
  if (j.id && j.jobId != null) existing[String(j.jobId)] = j.id;
}

return $('Parser triage Veille').all().map((it) => {
  const c = it.json;
  const airtableId = existing[String(c.jobId)] || null;
  return { json: { ...c, action: airtableId ? 'update' : 'create', airtableId } };
});

// Nœud n8n "Filtrer & préparer" (Code, runOnceForAllItems)
// Décode le corps des emails, applique les règles déterministes LinkedIn,
// extrait URL/Poste/Lieu/Mode pour les confirmations Envoyé, et construit
// le prompt Claude. Sortie : un item par email à classifier.
//
// Les alertes d'offres LinkedIn (jobalerts-noreply) ne sont plus ignorées :
// leur digest text/plain est découpé en cartes (une par offre) taguées
// kind:'veille'. Un Switch en aval ("Veille ?") sépare kind:'veille' du flux
// Candidatures (kind:'candidature'). Cf. veille-jobalerts.feature.md.

const items = $input.all();
const results = [];

const decodeB64 = (data) => {
  if (!data) return '';
  try { return Buffer.from(data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8'); }
  catch (e) { return ''; }
};

const extractText = (parts) => {
  if (!Array.isArray(parts)) return '';
  let text = '';
  for (const part of parts) {
    if (part.mimeType === 'text/plain' && part.body?.data) text += decodeB64(part.body.data) + ' ';
    else if (Array.isArray(part.parts)) text += extractText(part.parts);
  }
  return text;
};

// Lit un en-tête depuis le dict normalisé du nœud Gmail v2 (clés minuscules,
// valeurs de la forme "Nom: valeur").
const headerFromMap = (email, name) => {
  const h = email.headers;
  if (h && typeof h === 'object' && !Array.isArray(h)) {
    const raw = h[name.toLowerCase()];
    if (raw) return String(raw).replace(new RegExp('^\\s*' + name + '\\s*:\\s*', 'i'), '').trim();
  }
  return '';
};

// Récupère un en-tête quel que soit le format de sortie du nœud Gmail :
//  - brut (get full)            : email.payload.headers = [{name, value}]
//  - normalisé (node v2, simple:false) : champ direct minuscule (email.subject / email.date / …)
//    + dict email.headers {<nom-minuscule>: "Nom: valeur"}
// ⚠️ Le nœud "Gmail — Emails de la veille" renvoie la forme NORMALISÉE (pas de payload) :
// sans ce support, subject/from/date/domain remontaient tous vides (dates jamais écrites,
// règles LinkedIn forcées et filtrage jobalerts inopérants).
const getHeader = (email, name) => {
  const headers = email.payload?.headers;
  if (Array.isArray(headers)) {
    const found = headers.find(h => (h.name || '').toLowerCase() === name.toLowerCase());
    if (found) return found.value || '';
  }
  const low = name.toLowerCase();
  if (typeof email[low] === 'string' && email[low]) return email[low];
  const fromMap = headerFromMap(email, name);
  if (fromMap) return fromMap;
  const cap = name.charAt(0).toUpperCase() + name.slice(1);
  return email[name] || email[cap] || '';
};

const cutName = (s) => s.split(/\s[-|–—:]\s|\n|\bpour\b|\bfor\b/i)[0].trim().slice(0, 60);
const escRe = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Normalise vers les valeurs FR utilisées dans Airtable Candidatures : "À distance" / "Hybride" / "Sur site"
const cleanMode = (raw) => {
  const m = String(raw || '').toLowerCase();
  if (/(à\s*distance|\ba\s*distance\b|remote|télétravail|teletravail|full\s*remote)/.test(m)) return 'À distance';
  if (/(hybride|hybrid)/.test(m)) return 'Hybride';
  if (/(sur\s*(?:site|place)|on[-\s]?site|présentiel|presentiel)/.test(m)) return 'Sur site';
  return '';
};

// Trouve une URL d'offre LinkedIn dans un texte (HTML ou plain)
const findLinkedInJobUrl = (text) => {
  if (!text) return '';
  const m = String(text).match(/https?:\/\/(?:[\w.-]+\.)?linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)/i);
  return m ? `https://www.linkedin.com/jobs/view/${m[1]}/` : '';
};

// Cherche l'URL d'offre dans toutes les parties du payload (plain + html)
const findLinkedInJobUrlInPayload = (payload) => {
  if (!payload) return '';
  if (payload.body?.data) {
    const u = findLinkedInJobUrl(decodeB64(payload.body.data));
    if (u) return u;
  }
  if (Array.isArray(payload.parts)) {
    for (const p of payload.parts) {
      const u = findLinkedInJobUrlInPayload(p);
      if (u) return u;
    }
  }
  return '';
};

// --- Parseur de digest d'alertes emploi LinkedIn (jobalerts-noreply) ---
// Le corps text/plain liste les offres en blocs séparés par des lignes de tirets :
//   <Poste> / <Employeur> / <Lieu> / [badge…] / "Voir l'offre d'emploi : <URL …/jobs/view/JOBID/…>"
// Validé sur emails réels (2026-06-16). Pas de description du poste dans l'email
// (contrainte fiche) → on n'extrait que titre/employeur/lieu/mode + jobId/URL.
// Renvoie une carte par jobId (dédup intra-email ; dédup inter-jours = upsert Airtable).
const VEILLE_BADGES = /^(Top candidat|Croissance rapide|Recrutement actif|Cette entreprise recrute activement|Soyez parmi les premiers|Postulez avec|Candidature simplifiée|Easy Apply|Reprend contact|Forte affinité|Promu|En vedette|Actively recruiting|Be an early applicant|Top applicant|Salaire\b|\d+\s+relation)/i;

const parseJobAlertDigest = (plain) => {
  const cards = [];
  if (!plain) return cards;
  const seen = new Set();
  // Nom de l'alerte (recherche LinkedIn enregistrée) — contexte utile au triage
  const alertM = plain.match(/Votre alerte Emploi pour\s+(.+)/i);
  const alertName = alertM ? alertM[1].trim().slice(0, 200) : '';
  const blocks = plain.split(/\n[ \t]*-{3,}[ \t]*\n/);
  for (const block of blocks) {
    const jm = block.match(/linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)/i);
    if (!jm) continue;                       // en-tête / pied de page sans offre
    const jobId = jm[1];
    if (seen.has(jobId)) continue;           // dédup intra-email
    seen.add(jobId);
    const url = `https://www.linkedin.com/jobs/view/${jobId}/`;
    const lines = block.split('\n')
      .map(l => l.replace(/\s+/g, ' ').trim())
      .filter(Boolean)
      .filter(l => !/^Votre alerte Emploi pour/i.test(l))
      .filter(l => !/^Voir l.offre d.emploi\s*:/i.test(l))
      .filter(l => !VEILLE_BADGES.test(l));
    const poste = (lines[0] || '').slice(0, 200);
    const employeur = (lines[1] || '').slice(0, 120);
    let lieu = (lines[2] || '').slice(0, 120);
    // Mode parfois accolé au lieu : "France (à distance)", "Paris (Hybride)"
    let mode = '';
    const lp = lieu.match(/^(.*?)\s*\(([^)]+)\)\s*$/);
    if (lp) { const m = cleanMode(lp[2]); if (m) { mode = m; lieu = lp[1].trim(); } }
    if (!mode) mode = cleanMode(lieu);
    cards.push({ jobId, url, employeur, poste, lieu, mode, alertName });
  }
  return cards;
};

for (const item of items) {
  const email = item.json;

  const subject = getHeader(email, 'Subject');
  // From : objet normalisé {value:[{address,name}]} (node v2) OU en-tête brut.
  const fromObj = email.from;
  let fromRaw = '';
  if (fromObj && typeof fromObj === 'object' && Array.isArray(fromObj.value) && fromObj.value[0]) {
    const v = fromObj.value[0];
    fromRaw = v.name ? `${v.name} <${v.address || ''}>` : (v.address || '');
  } else {
    fromRaw = getHeader(email, 'From');
  }
  const dateRaw = getHeader(email, 'Date'); // node v2 : déjà ISO (ex. 2026-06-15T22:09:30.000Z)
  const fromEmail = (
    (fromObj && typeof fromObj === 'object' && fromObj.value && fromObj.value[0] && fromObj.value[0].address)
    || (fromRaw.match(/<([^>]+)>/) || [])[1]
    || fromRaw.trim()
    || ''
  ).toLowerCase();
  const domain = fromEmail.includes('@') ? fromEmail.split('@')[1] : '';
  const snippet = email.snippet
    || (typeof email.text === 'string' ? email.text.replace(/\s+/g, ' ').trim().slice(0, 400) : '');
  const isLinkedIn = domain.includes('linkedin.com');

  // Règles déterministes LinkedIn (sur sujet + aperçu)
  let forcedReponse = null;
  let forcedSociete = null;
  if (isLinkedIn) {
    const head = `${subject}\n${snippet}`;
    let m;
    if ((m = head.match(/your application was sent to\s+(.+)/i)) ||
        (m = head.match(/votre candidature a été envoyée à\s+(.+)/i)) ||
        (m = head.match(/candidature(?:\s+a(?:\s+bien)?\s+été)?\s+envoyée\s+à\s+(.+)/i))) {
      forcedReponse = 'Envoyé'; forcedSociete = cutName(m[1]);
    } else if ((m = head.match(/your application was viewed by\s+(.+)/i)) ||
               (m = head.match(/candidature a été consultée par\s+(.+)/i))) {
      forcedReponse = 'A/R'; forcedSociete = cutName(m[1]);
    } else if ((m = head.match(/derni[eè]re nouvelle de\s+(.+)/i))) {
      forcedReponse = 'Non'; forcedSociete = cutName(m[1]);
    }
  }

  // Alertes d'offres LinkedIn -> branche Veille (parse du digest en cartes)
  if (!forcedReponse && fromEmail === 'jobalerts-noreply@linkedin.com') {
    let plain = '';
    if (email.payload && Array.isArray(email.payload.parts)) plain = extractText(email.payload.parts);
    else if (email.payload?.body?.data) plain = decodeB64(email.payload.body.data);
    if (!plain) plain = email.plaintextBody || email.text || '';
    for (const c of parseJobAlertDigest(plain)) {
      results.push({
        json: {
          kind: 'veille',
          jobId: c.jobId, url: c.url,
          employeur: c.employeur, poste: c.poste, lieu: c.lieu, mode: c.mode,
          alertName: c.alertName,
          emailId: email.id || '', date: dateRaw,
        },
      });
    }
    continue; // ne pas envoyer ces emails dans le flux Candidatures
  }

  let bodyRaw = '';
  if (email.payload) {
    if (Array.isArray(email.payload.parts)) bodyRaw = extractText(email.payload.parts);
    else if (email.payload.body?.data) bodyRaw = decodeB64(email.payload.body.data);
  }
  if (!bodyRaw) bodyRaw = email.text || email.html || snippet || '';

  let bodyClean = String(bodyRaw).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (bodyClean.length > 2500) bodyClean = bodyClean.slice(0, 1800) + ' […] ' + bodyClean.slice(-700);

  // Enrichissement LinkedIn (Envoyé uniquement) — URL / Poste / Lieu / Mode
  let forcedUrl = '';
  let forcedPoste = null;
  let forcedLieu = null;
  let forcedMode = null;
  if (isLinkedIn && forcedReponse === 'Envoyé' && forcedSociete) {
    forcedUrl = findLinkedInJobUrlInPayload(email.payload);

    // Pattern : "<Société> <Poste> <Société> · <Lieu> (<Mode>?) ... Candidature/Application/Voir/View"
    const escSoc = escRe(forcedSociete);
    const stop = '(?:\\s+Candidature\\s+envoyée|\\s+Application\\s+sent|\\s+View\\s+job|\\s+Voir\\s+l|\\s+Postuler|$)';
    const re = new RegExp(
      `${escSoc}\\s+([^·•]+?)\\s+${escSoc}\\s*[·•]\\s*([^·•]+?)${stop}`,
      'i'
    );
    const mm = bodyClean.match(re);
    if (mm) {
      forcedPoste = mm[1].trim().slice(0, 200);
      const meta = mm[2].trim();
      const lm = meta.match(/^(.+?)\s*(?:\(([^)]+)\))?\s*$/);
      if (lm) {
        forcedLieu = lm[1].trim().slice(0, 100);
        forcedMode = cleanMode(lm[2] || meta);
      }
    }
  }

  const customId = ('m_' + (email.id || String(results.length)))
    .replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 64);

  const claudePrompt = `Analyse cet email de candidature à l'emploi (en français) et classe la réponse de l'employeur.

Expéditeur : ${fromRaw}
Domaine expéditeur : ${domain}
Sujet : ${subject}
Corps : ${bodyClean || snippet}

Réponds UNIQUEMENT avec ce JSON, sans texte ni balises autour :
{"recrutement": true/false, "societe": "... ou null", "poste": "... ou null", "reponse": "A/R|Oui|Non", "confidence": "high|medium|low", "note": "1 phrase"}

DÉFINITIONS
- recrutement=true : email lié à une candidature précise (accusé de réception d'ATS, refus, invitation entretien, message d'un recruteur sur une candidature).
- recrutement=false : alertes/offres non sollicitées, newsletters ; emails d'AUTHENTIFICATION / code de connexion / vérification ; emails de BIENVENUE / création de compte / inscription à une plateforme ; invitations à une CONFÉRENCE / webinaire / événement (≠ entretien d'embauche) ; notifs bancaires, factures, pub, réseaux sociaux.
- societe : l'ENTREPRISE qui recrute. Si elle n'est pas explicite, DÉDUIS-LA de la signature, de l'adresse postale, du logo/nom cité dans le corps, ou du domaine de l'expéditeur. Jamais la plateforme/ATS ni le cabinet (ignorer Welcome to the Jungle, Greenhouse, Lever, Workday, LinkedIn). null seulement si vraiment introuvable.
- poste : déduis l'intitulé depuis le sujet, le corps ou la signature. null si introuvable.

CLASSEMENT DE reponse — lis le CORPS, pas seulement l'objet :
- "A/R" = accusé de réception, AUCUNE décision : « bien reçu votre candidature », « candidature enregistrée », « merci pour votre candidature », confirmation automatique.
- "Non" = refus : « ne donnerons pas suite », « profil n'a pas été retenu », « malheureusement », « regret », « unfortunately ».
- "Oui" = suite positive RÉELLE : invitation entretien/échange/appel/visio, test ou screening de sélection, « souhaitons vous rencontrer », « vos disponibilités », « prochaine étape ». PAS une invitation à une conférence/événement ni une simple inscription.

RÈGLES
- Un accusé de réception n'est PAS un refus. A/R ≠ Non ≠ Oui.
- En cas de doute entre les trois (si c'est bien du recrutement) → "A/R".`;

  results.push({
    json: {
      kind: 'candidature',
      customId, emailId: email.id || '', subject, fromRaw, fromEmail,
      date: dateRaw, domain, snippet, bodyClean, claudePrompt,
      forcedReponse, forcedSociete, forcedUrl, forcedPoste, forcedLieu, forcedMode,
    },
  });
}

return results;

const items = $input.all();

const requests = items.map((item) => ({
  custom_id: item.json.customId,
  params: {
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 512,
    system: 'Tu extrais des infos depuis des emails de recrutement. Réponds UNIQUEMENT en JSON valide.',
    messages: [{ role: 'user', content: item.json.claudePrompt }],
  },
}));

// Garde-fou: un batch vide renverrait un 400 côté Anthropic.
if (requests.length === 0) {
  throw new Error('Aucun email à classifier (0 requête) — rien à envoyer au batch.');
}

return [{ json: { requests, count: requests.length } }];

// Nœud n8n "Matcher & décider" (Code, runOnceForAllItems)
// Lit les résultats du batch (JSONL) + la liste Airtable, rapproche chaque
// email d'une candidature existante, et décide : create / update / skip / review.
// Propage en sortie les enrichissements LinkedIn (URL, Lieu, Mode).

const DENY = new Set(['indigoneo']);

// Hiérarchie des statuts : on n'avance que vers l'avant
const RANK = { '': 0, 'neant': 0, 'envoye': 1, 'a/r': 2, 'ar': 2, 'oui': 3, 'non': 3 };
const rankOf = (rp) => RANK[String(rp || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')] ?? 0;

const toIso = (s) => { if (!s) return ''; const d = new Date(s); return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10); };

const normalize = (s) => String(s || '')
  .toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/\b(sas|sasu|sa|sarl|inc|ltd|llc|gmbh|group|groupe|technologies|tech|recruitment|recrutement|staffing)\b/g, '')
  .replace(/[^a-z0-9]/g, '');

const getField = (f, name) => {
  if (!f) return '';
  if (f[name] != null) return f[name];
  const norm = (s) => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const target = norm(name);
  for (const k of Object.keys(f)) if (norm(k) === target) return f[k];
  return '';
};

const indexed = $input.all().map((i) => {
  const f = i.json.fields || i.json;
  return {
    id: getField(f, 'id') || i.json.id,
    societe: getField(f, 'societe'),
    poste: getField(f, 'poste'),
    reponse: getField(f, 'reponse'),
    key: normalize(getField(f, 'societe')),
  };
});

const findMatch = (societe, meta) => {
  const keyS = normalize(societe);
  if (keyS.length > 1) {
    const m = indexed.find(r => r.key && (r.key === keyS || r.key.includes(keyS) || keyS.includes(r.key)));
    if (m) return m;
  }
  const hay = normalize(`${meta.subject || ''} ${meta.snippet || ''} ${meta.bodyClean || ''} ${meta.fromRaw || ''}`);
  if (hay) {
    const hits = indexed
      .filter(r => r.key && r.key.length >= 4 && hay.includes(r.key))
      .sort((a, b) => b.key.length - a.key.length);
    if (hits.length) return hits[0];
  }
  const keyD = normalize((meta.domain || '').split('.')[0]);
  if (keyD.length > 2) {
    const m = indexed.find(r => r.key && (r.key.includes(keyD) || keyD.includes(r.key)));
    if (m) return m;
  }
  return null;
};

const metaById = {};
for (const it of $('Filtrer & préparer').all()) {
  metaById[it.json.customId] = it.json;
}

const r = $('Récupérer résultats').first().json;
const raw = (typeof r === 'string') ? r : (r.data || r.body || r.text || '');
const lines = String(raw).split('\n').map(l => l.trim()).filter(Boolean);

const out = [];
for (const line of lines) {
  let entry;
  try { entry = JSON.parse(line); } catch (e) { continue; }

  const meta = metaById[entry.custom_id];
  if (!meta) continue;

  let extracted = { recrutement: false, societe: null, poste: null, reponse: 'A/R', confidence: 'low', note: '' };
  if (entry.result && entry.result.type === 'succeeded') {
    try {
      const text = entry.result.message?.content?.[0]?.text || '';
      const clean = text.replace(/```json\n?/g, '').replace(/```/g, '').trim();
      extracted = { ...extracted, ...JSON.parse(clean) };
    } catch (e) { /* défaut conservé */ }
  }

  const forced = !!meta.forcedReponse;
  if (extracted.recrutement !== true && !forced) continue;

  // société + fiabilité (forcée OU extraite par Claude = fiable ; fallback domaine = non fiable)
  let societe, societeReliable;
  if (meta.forcedSociete) { societe = meta.forcedSociete; societeReliable = true; }
  else if (extracted.societe && extracted.societe !== 'null') { societe = extracted.societe; societeReliable = true; }
  else { societe = meta.domain ? meta.domain.split('.')[0] : ''; societeReliable = false; }

  // Poste : préfère l'extraction LinkedIn déterministe, sinon Claude
  const poste = meta.forcedPoste
    ? meta.forcedPoste
    : ((extracted.poste && extracted.poste !== 'null') ? extracted.poste : '');

  // Enrichissements LinkedIn (vides pour les autres emails)
  const lieu = meta.forcedLieu || '';
  const mode = meta.forcedMode || '';
  const linkedinUrl = meta.forcedUrl || '';

  const reponse = forced
    ? meta.forcedReponse
    : (['Oui', 'Non', 'A/R'].includes(extracted.reponse) ? extracted.reponse : 'A/R');

  if (DENY.has(normalize(societe))) continue;

  const match = findMatch(societe, meta);

  let action, airtableId = null;
  if (match) {
    airtableId = match.id;
    action = rankOf(reponse) > rankOf(match.reponse) ? 'update' : 'skip';
  } else if (societeReliable && normalize(societe).length >= 2) {
    action = 'create';
  } else {
    action = 'review';
  }

  out.push({
    json: {
      action, airtableId, societe, poste, reponse,
      lieu, mode, linkedinUrl,
      subject: meta.subject, fromRaw: meta.fromRaw, date: toIso(meta.date),
      note: extracted.note || '',
      gmailLink: meta.emailId ? `https://mail.google.com/mail/u/0/#all/${meta.emailId}` : '',
      domain: meta.domain, emailId: meta.emailId,
      confidence: extracted.confidence || 'low',
      forced, existingReponse: match ? match.reponse : null,
    },
  });
}

// Dédoublonnage intra-run : create/update oui ; review JAMAIS (l'upsert Airtable gère le cross-run)
const best = new Map();
const reviews = [];
for (const o of out) {
  if (o.json.action === 'review') { reviews.push(o); continue; }
  const k = (o.json.action === 'create') ? ('soc:' + normalize(o.json.societe)) : ('id:' + o.json.airtableId);
  const prev = best.get(k);
  if (!prev || rankOf(o.json.reponse) > rankOf(prev.json.reponse)) best.set(k, o);
}
return [...best.values(), ...reviews];

// Nœud n8n "Prépa triage Veille" (Code, runOnceForAllItems)
// Construit UNE seule requête de triage pour TOUTES les offres du jour (évite le
// rate-limit Anthropic d'un appel par carte, et laisse l'IA comparer les offres
// entre elles). Sort un unique item { prompt, cards } consommé par l'appel Claude.

const cards = $input.all().map((it) => it.json);

const PROFIL = `Profil candidat : consultant senior independant, 25 ans d'experience, 100% assurance & finance. Cherche mission freelance/contract/interim (CDI senior finance possible), full remote ou hybride privilegie, TJM >= 1000 EUR/j. Ouvert a l'international en remote (EMEA, Amerique du Nord, APAC).`;

const RUBRIQUE = `Classe CHAQUE offre par pertinence pour ce profil, en te basant sur titre + employeur + lieu UNIQUEMENT (pas de description disponible).
- "Haute" = coeur de cible a seniorite senior : transformation finance/assurance, PMO / Program / Project Manager en finance/assurance/banque/asset management, AMOA / Business Analyst finance, Interim Finance Manager / Head of, comptabilite des investissements (IFRS 9, IFRS 17, Solvency II, fund accounting, sous-ledger titres), reporting reglementaire (ACPR, ORSA, QRT, RSR/SFCR), implementation SimCorp / Clearwater / Bloomberg / OMS, migration & apurement comptable. Un lieu en Europe/EMEA, a l'etranger ou non precise NE PENALISE PAS (remote international accepte).
- "Moyenne" = finance/PMO senior hors assurance stricte (corporate finance, banque generaliste, FP&A senior), ou coeur de cible avec un doute reel sur la seniorite.
- "Hors-cible" = junior/stage/alternance, OU metier hors finance/assurance : IT/dev pur, e-commerce, energie, marketing, RH, commercial, conseil generaliste sans ancrage finance/assurance.
REGLES : ne pas inventer d'info ; l'ABSENCE de mention "remote/teletravail" n'est PAS un signal negatif (les alertes ne le precisent jamais) ; un "Project Manager" sans secteur finance/assurance identifiable = Hors-cible ; en cas d'hesitation entre Haute et Moyenne sur une offre clairement finance/assurance senior, choisir Haute.`;

const lignes = cards
  .map((c, i) => `${i + 1}. Poste: ${c.poste || ''} | Employeur: ${c.employeur || ''} | Lieu: ${c.lieu || ''}`)
  .join('\n');

const prompt = `${PROFIL}\n\n${RUBRIQUE}\n\nReponds UNIQUEMENT avec un tableau JSON, un objet par offre, DANS L'ORDRE, sans texte autour :\n[{"i":1,"pertinence":"Haute|Moyenne|Hors-cible","raison":"<=12 mots en francais"}]\n\nOFFRES :\n${lignes}`;

return [{ json: { prompt, cards, count: cards.length } }];

// Nœud n8n "Parser triage Veille" (Code, runOnceForAllItems)
// Lit la réponse unique du triage (tableau JSON, un objet par offre dans l'ordre)
// et la rattache à chaque carte par index. Sort une carte par offre (jobId + pertinence).
const src = $('Prépa triage Veille').first().json;
const cards = src.cards || [];

let arr = [];
try {
  const txt = ($json && $json.content && $json.content[0] && $json.content[0].text) || '';
  const m = txt.match(/\[[\s\S]*\]/);
  if (m) arr = JSON.parse(m[0]);
} catch (e) { /* tableau vide => pertinence vide, à trier à la main */ }

const byI = {};
for (const o of arr) { if (o && o.i != null) byI[Number(o.i)] = o; }

const valid = ['Haute', 'Moyenne', 'Hors-cible'];
const toIso = (s) => { if (!s) return ''; const d = new Date(s); return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10); };

return cards.map((c, idx) => {
  const o = byI[idx + 1] || {};
  let pertinence = o.pertinence;
  if (!valid.includes(pertinence)) pertinence = '';
  return {
    json: {
      jobId: c.jobId, employeur: c.employeur, poste: c.poste, lieu: c.lieu,
      mode: c.mode, url: c.url, alertName: c.alertName, date: toIso(c.date),
      pertinence, raison: o.raison || '',
    },
  };
});

// Nœud n8n "Veille décider" (Code, runOnceForAllItems)
// Décide create vs update pour chaque carte, SANS dépendre du pairedItem :
// le nœud "Chercher Veille" (search Airtable) casse l'appariement 1-pour-1, donc
// on rapproche en JS via .all() (même principe que "Matcher & décider").
// Index des lignes Veille existantes (résultats du search) : jobId -> id Airtable.
const existing = {};
for (const it of $('Chercher Veille').all()) {
  const j = it.json || {};
  if (j.id && j.jobId != null) existing[String(j.jobId)] = j.id;
}

return $('Parser triage Veille').all().map((it) => {
  const c = it.json;
  const airtableId = existing[String(c.jobId)] || null;
  return { json: { ...c, action: airtableId ? 'update' : 'create', airtableId } };
});
